#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    long long curTime = 0;
    long long pending = 0;
    bool hasEvent = false;

    map<int, long long> total;
    map<int, long long> start;
    set<int> friends;

    for (int i = 0; i < N; i++) {
        char c;
        int x;
        cin >> c >> x;

        if (c == 'T') {
            pending += x;
        } else {
            if (!hasEvent) {
                curTime = 0;
                hasEvent = true;
                pending = 0;
            } else {
                if (pending > 0) curTime += pending;
                else curTime += 1;
                pending = 0;
            }

            friends.insert(x);

            if (c == 'R') {
                if (!total.count(x)) total[x] = 0;
                start[x] = curTime;
            } else {
                if (!total.count(x)) total[x] = 0;
                if (start.count(x)) {
                    total[x] += curTime - start[x];
                    start.erase(x);
                }
            }
        }
    }

    for (int f : friends) {
        long long ans = total[f];
        if (start.count(f)) ans = -1;
        cout << f << ' ' << ans << '\n';
    }

    return 0;
}
